def zone_fees(areas_km: dict[str, float]) -> dict[str, int]:
    """Calculate delivery fees for each area based on distance."""
    fees = {}
    for area, distance in areas_km.items():
        if distance < 0:
            fees[area] = -1
        else:
            # Assume a base fee of 50 shillings per km
            fees[area] = int(distance * 50)
    return fees
